46	async function loadSmtp() {
47	  const rows = await db.setting.findMany({
48	    where: { key: { in: ["smtp_host", "smtp_port", "smtp_user", "smtp_pass", "smtp_from", "smtp_secure"] } },
49	  });
50	  const s = Object.fromEntries(rows.map((r) => [r.key, r.value]));
51	  const host = s.smtp_host || process.env.SMTP_HOST || "";
52	  const from = s.smtp_from || process.env.SMTP_FROM || `Nxeon <no-reply@${(process.env.APP_URL ?? "localhost").replace(/^https?:\/\//, "")}>`;
53	  return {
54	    host,
55	    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
56	    user: s.smtp_user || process.env.SMTP_USER || "",
57	    pass: smtpPassPlain(s.smtp_pass) || process.env.SMTP_PASS || "",
58	    secure: (s.smtp_secure ?? process.env.SMTP_SECURE) === "true",
59	    from,
60	  };
61	}
