63	/**
64	 * Reply-To for a HUMAN support reply (live-chat follow-up, manual ticket
65	 * reply, etc.) — `support@nxeon.cloud` rather than the transactional no-reply
66	 * address, so hitting "Reply" in the customer's mail client actually reaches
67	 * someone. Pass as `replyTo`, NOT `from`: the mail relay (Mailcow) enforces
68	 * sender-address ownership per authenticated mailbox and rejects a `from`
69	 * override for an address the SMTP user doesn't own (confirmed — a live send
70	 * bounced 553 5.7.1 "not owned by user noreply@nxeon.cloud"). Reply-To has no
71	 * such restriction and every mainstream mail client honors it on Reply.
72	 */
73	export async function supportReplyAddress(): Promise<string> {
74	  const { supportEmail } = await import("./settings");
75	  return `Nxeon Support <${await supportEmail()}>`;
76	}
