83	function transport(c: Awaited<ReturnType<typeof loadSmtp>>) {
84	  if (!c.host) {
85	    // Local MTA fallback (Postfix/sendmail on the host)
86	    return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
87	  }
88	  // When the SMTP host is an internal IP (e.g. the mail VM at 10.20.0.10) but the
89	  // server presents a cert for its hostname (mail.nxeon.cloud), TLS validation
90	  // fails on an IP mismatch. `SMTP_TLS_SERVERNAME` lets us keep cert verification
91	  // on while telling TLS the name to validate against (and sets SNI accordingly).
92	  const servername = process.env.SMTP_TLS_SERVERNAME || undefined;
93	  return nodemailer.createTransport({
94	    host: c.host,
95	    port: c.port,
96	    secure: c.secure,
97	    auth: c.user ? { user: c.user, pass: c.pass } : undefined,
98	    ...(servername ? { tls: { servername } } : {}),
99	  });
100	}
