107	/**
108	 * Build the invoice attachment for an email. We now attach a REAL PDF, rendered
109	 * server-side by `lib/invoice-pdf.ts` (pdfkit — pure JS, no headless browser),
110	 * so accounting departments receive an actual `application/pdf` document rather
111	 * than the print-ready HTML that only became a PDF via the recipient's browser.
112	 * It carries the same branded layout and identifier as the on-site PDF download.
113	 */
114	async function invoiceAttachment(invoiceId: string): Promise<MailAttachment | null> {
115	  try {
116	    const invoice = await db.invoice.findUnique({
117	      where: { id: invoiceId },
118	      include: { user: { select: { name: true, email: true } } },
119	    });
120	    if (!invoice) return null;
121	    // Use the SAME branding the dashboard and the download route use, so the
122	    // invoice a customer receives by email carries the identifier they can quote
123	    // back at you — and the seller block, which only reaches emailed invoices
124	    // through this path. Previously this hardcoded `#00012`-style numbering while
125	    // every on-screen copy showed `INV-00012`: the customer and the support agent
126	    // would have been reading two different invoice numbers for one invoice.
127	    const branding = await invoiceBranding();
128	    const pdf = await renderInvoicePDF(invoice, invoice.user, branding);
129	    const filename = invoicePdfFilename(invoice.number, branding.numberPrefix);
130	    return { filename, content: pdf, contentType: "application/pdf" };
131	  } catch (e) {
132	    console.error("[mailer] failed to build invoice attachment:", e);
133	    return null;
134	  }
135	}
