137	export type SendMailOpts = {
138	  to: string;
139	  /**
140	   * Optional From override. Falls back to the admin `smtp_from` setting when
141	   * omitted (every existing transactional/marketing send is unaffected).
142	   * CAVEAT: the mail relay (Mailcow) enforces sender-address ownership per
143	   * authenticated SMTP user — an address the configured `smtp_user` doesn't
144	   * own gets rejected outright (553 5.7.1 "not owned by..."), so this only
145	   * works for addresses actually provisioned to that mailbox. For a support
146	   * reply that needs to look like it's from a different address, use
147	   * `replyTo` (see `supportReplyAddress()`) instead — it has no such
148	   * restriction.
149	   */
150	  from?: string;
151	  /** Optional Reply-To (e.g. route a contact-form reply straight to the sender). */
152	  replyTo?: string;
153	  /** Explicit subject. Optional when `template` is provided. */
154	  subject?: string;
155	  /** Explicit pre-rendered HTML. Optional when `template` is provided. */
156	  html?: string;
157	  text?: string;
158	  /** DB template key — when set (and no explicit `html`), the body is rendered via `renderTemplate`. */
159	  template?: string;
160	  /** Variables for `{{placeholders}}` when rendering from a template. */
161	  vars?: Record<string, unknown>;
162	  /** Attribution for the EmailLog row. */
163	  userId?: string | null;
164	  /** When set, attaches the invoice (auto for receipt/invoice_new/renewal_reminder templates). */
165	  invoiceId?: string;
166	  /** Extra attachments. */
167	  attachments?: MailAttachment[];
168	  /**
169	   * What KIND of message this is, for the notification-preference policy in
170	   * `lib/prefs.ts`. Supply it together with `userId` and this function enforces
171	   * the customer's choice centrally — see the gate below.
172	   *
173	   * Omitting it means "always send", which is the safe default: a message must
174	   * never be dropped because someone forgot to classify it.
175	   */
176	  kind?: NotifyKind;
177	  /**
178	   * When set, this is a MARKETING send and the message carries RFC 8058 one-click
179	   * unsubscribe headers pointing at this URL:
180	   *   List-Unsubscribe: <https://…/api/unsubscribe?token=…>
181	   *   List-Unsubscribe-Post: List-Unsubscribe=One-Click
182	   * Transactional sends never pass this, so they never get the headers. There is
183	   * no list-unsubscribe MAILBOX configured, so only the https one-click URL is
184	   * advertised (a mailto with no automation behind it would be worse than none).
185	   */
186	  listUnsubscribeUrl?: string;
187	};
