189	/** Matches an anchor's href attribute value (double-quoted, http/https only —
190	 *  every template composes links via `appUrl()`/`path()`, never a bare mailto
191	 *  or relative href, so this is the complete surface). */
192	const HREF_RE = /href="(https?:\/\/[^"]+)"/g;
193	
194	/**
195	 * Rewrite every trackable anchor in `html` to route through the click-redirect
196	 * endpoint, and append an invisible open-tracking pixel before `</body>`.
197	 *
198	 * An anchor is SKIPPED (left exactly as-is, not tracked) when its href carries
199	 * a bearer secret (password reset, email verification, invite tokens, …) —
200	 * see `containsSecretQueryParam`. The real destination for every rewritten
201	 * link is returned in `links`, positionally indexed to match the `/click/N`
202	 * URLs, for the caller to persist on the EmailLog row; a secret-bearing href
203	 * never enters that array, so it can never be re-served by the redirect route.
204	 */
205	function injectEmailTracking(html: string, emailLogId: string): { html: string; links: string[] } {
206	  const links: string[] = [];
207	  const base = appUrl();
208	  let out = html.replace(HREF_RE, (full, href: string) => {
209	    if (containsSecretQueryParam(href)) return full;
210	    const idx = links.length;
211	    links.push(href);
212	    return `href="${base}/api/track/email/${emailLogId}/click/${idx}"`;
213	  });
214	  const pixel = `<img src="${base}/api/track/email/${emailLogId}/open" width="1" height="1" alt="" style="display:block;border:0;outline:none;" />`;
215	  out = out.includes("</body>") ? out.replace("</body>", `${pixel}</body>`) : out + pixel;
216	  return { html: out, links };
217	}
