219	/**
220	 * Send an email. Never throws — logs and returns false on failure so callers
221	 * don't break flows. EVERY attempt is written to `EmailLog` (SENT on success,
222	 * FAILED + error otherwise) for the admin Logs viewer.
223	 *
224	 * NOTIFICATION PREFERENCES are enforced HERE, not at the call sites.
225	 * `User.notificationPrefs` was a column the customer edited and nothing read, so
226	 * turning off "email me about billing" changed nothing. Gating each send site
227	 * individually would have fixed today's sites and left every future one to
228	 * re-introduce the bug; gating centrally means a new send site inherits the
229	 * policy automatically and per-site checks become defence in depth.
230	 *
231	 * Two deliberate properties, both fail-open:
232	 *   - no `kind` (or no `userId`) → send. Unclassified is never silenced.
233	 *   - `mayDeliverTo` returns true for anything non-suppressible without touching
234	 *     the database, and also on a lookup error. A payment-failure or suspension
235	 *     warning must not be lost because a preference read failed.
236	 */
237	export async function sendMail(opts: SendMailOpts): Promise<boolean> {
238	  // Preference gate. CRITICAL kinds (payment failed, suspension, security
239	  // changes, data loss…) are declared non-suppressible in lib/prefs.ts and short
240	  // -circuit to true, so this costs nothing on the paths that matter most.
241	  if (opts.kind && opts.userId) {
242	    const allowed = await mayDeliverTo(opts.userId, opts.kind, "email");
243	    if (!allowed) {
244	      console.log(`[mail] suppressed ${opts.kind} to user ${opts.userId} by preference`);
245	      return false;
246	    }
247	  }
248	
249	  // Resolve subject/html: prefer explicit values, otherwise render the template.
250	  let subject = opts.subject ?? "";
251	  let html = opts.html ?? "";
252	  const templateKey = opts.template ?? null;
253	
254	  if (templateKey && !opts.html) {
255	    const rendered = await renderTemplate(templateKey, opts.vars ?? {});
256	    subject = opts.subject ?? rendered.subject;
257	    html = rendered.html;
258	  }
259	
260	  // Plain-text fallback derived from the UNTRACKED html — a text-only client
261	  // shows real URLs, not opaque tracking-redirect ones.
262	  const derivedText = opts.text ?? html.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
263	
264	  // Open/click tracking: mint the EmailLog id up front so the pixel + rewritten
265	  // link URLs baked into the outgoing HTML reference a row that exists by the
266	  // time anyone opens or clicks. Applied uniformly to every send; see
267	  // injectEmailTracking's own doc comment for what's deliberately excluded.
268	  const emailLogId = randomUUID();
269	  const tracked = injectEmailTracking(html, emailLogId);
270	  html = tracked.html;
271	
272	  // Assemble attachments (invoice auto-attaches for the relevant templates).
273	  const attachments: MailAttachment[] = [...(opts.attachments ?? [])];
274	  const wantInvoice = opts.invoiceId && (!templateKey || INVOICE_ATTACH_TEMPLATES.has(templateKey));
275	  if (wantInvoice && opts.invoiceId) {
276	    const att = await invoiceAttachment(opts.invoiceId);
277	    if (att) attachments.push(att);
278	  }
279	
280	  try {
281	    const c = await loadSmtp();
282	    if (!c.host && process.env.NXEON_LOCAL_MAIL !== "1") {
283	      console.warn("[mailer] not configured — skipping email:", subject);
284	      await recordEmail(opts.to, subject, templateKey, html, "FAILED", "SMTP not configured", opts.userId, emailLogId, tracked.links, opts.kind);
285	      return false;
286	    }
287	    const t = transport(c);
288	    // RFC 8058 one-click unsubscribe — MARKETING sends only (a `listUnsubscribeUrl`
289	    // is passed). Transactional sends omit it and get no such headers.
290	    const listHeaders = opts.listUnsubscribeUrl
291	      ? {
292	          "List-Unsubscribe": `<${opts.listUnsubscribeUrl}>`,
293	          "List-Unsubscribe-Post": "List-Unsubscribe=One-Click",
294	        }
295	      : undefined;
296	    await t.sendMail({
297	      from: opts.from || c.from,
298	      to: opts.to,
299	      replyTo: opts.replyTo || undefined,
300	      subject,
301	      html,
302	      text: derivedText,
303	      attachments: attachments.length ? attachments : undefined,
304	      ...(listHeaders ? { headers: listHeaders } : {}),
305	    });
306	    await recordEmail(opts.to, subject, templateKey, html, "SENT", null, opts.userId, emailLogId, tracked.links, opts.kind);
307	    return true;
308	  } catch (e) {
309	    console.error("[mailer] send failed:", e);
310	    await recordEmail(opts.to, subject, templateKey, html, "FAILED", String((e as Error)?.message ?? e), opts.userId, emailLogId, tracked.links, opts.kind);
311	    return false;
312	  }
313	}
