315	/**
316	 * Preferred path for DB-templated sends: render `key` with `vars`, send, log,
317	 * and (for billing templates) attach the invoice. Thin convenience over
318	 * `sendMail` for new callers.
319	 *
320	 * `kind` is forwarded to `sendMail`, which is the ONLY place the notification
321	 * policy is enforced. It used to be absent from this signature, so every send
322	 * routed through this wrapper was structurally incapable of honouring the
323	 * customer's "Account email" preference — a caller could not have opted in even
324	 * if it wanted to. That is the same class of defect as the column nothing read
325	 * (see `sendMail`), just one layer up: the gate exists, and the convenient path
326	 * quietly walks around it. Omitting `kind` still means "always send".
327	 */
328	export async function sendTemplate(
329	  key: string,
330	  to: string,
331	  vars: Record<string, unknown> = {},
332	  opts: {
333	    userId?: string | null;
334	    invoiceId?: string;
335	    attachments?: MailAttachment[];
336	    kind?: NotifyKind;
337	  } = {},
338	): Promise<boolean> {
339	  return sendMail({
340	    to,
341	    template: key,
342	    vars,
343	    userId: opts.userId,
344	    invoiceId: opts.invoiceId,
345	    attachments: opts.attachments,
346	    kind: opts.kind,
347	  });
348	}
