382	// ---- Transactional templates ----
383	//
384	// The full transactional catalog lives in `lib/email-templates.ts` (30+
385	// templates, all composed from the shared inline-styled components). It is
386	// re-exported here as `emails` so every existing call site — `import { emails }
387	// from "@/lib/mailer"` — keeps working unchanged. Each entry returns
388	// `{ template, subject, html }`; the six original signatures are preserved.
389	export type { BuiltEmail };
