391	// ===========================================================================
392	// Card billing & dunning templates
393	//
394	// Renewals apply wallet credit first, then auto-charge the customer's saved
395	// card for the remainder. When that charge fails we retry on day 1, 3 and 5 and
396	// only suspend once the retries are exhausted. These templates carry that flow.
397	//
398	// They live here rather than in `lib/email-templates.ts` only because this file
399	// is the one owned by the card-billing change; they are built with the same
400	// `build()` shape and the same shared components, so they render identically to
401	// the rest of the catalog.
402	// ===========================================================================
403	
404	/**
405	 * Number of automatic retries in the dunning sequence (day 1, day 3, day 5).
406	 * `paymentRetryFailed` uses it to tell the customer how many attempts are left,
407	 * so the worker's retry schedule and this copy must agree.
408	 */
409	export const DUNNING_RETRY_ATTEMPTS = 3;
410	
411	/**
412	 * Same composition helper as `lib/email-templates.ts` (which keeps its copy
413	 * module-private): eyebrow → heading → body blocks → single CTA → optional
414	 * footnote, wrapped with a preheader by the shared shell.
415	 */
416	function build(opts: {
417	  template: string;
418	  subject: string;
419	  preheader: string;
420	  eyebrow?: string;
421	  accent?: Accent;
422	  heading: string;
423	  blocks: string[];
424	  cta?: { href: string; label: string; accent?: Accent };
425	  note?: string;
426	}): BuiltEmail {
427	  const parts: string[] = [];
428	  if (opts.eyebrow) parts.push(emailEyebrow(opts.eyebrow, opts.accent ?? "violet"));
429	  parts.push(emailHeading(opts.heading));
430	  parts.push(...opts.blocks);
431	  if (opts.cta) parts.push(emailButton(opts.cta.href, opts.cta.label, opts.cta.accent ?? "violet"));
432	  if (opts.note) parts.push(emailNote(opts.note));
433	  return {
434	    template: opts.template,
435	    subject: opts.subject,
436	    html: wrapEmail(parts.join("\n"), { preheader: opts.preheader }),
437	  };
438	}
439	
440	/** Masked card display used wherever we echo the saved card back. */
441	const cardLabel = (last4: string) => `&bull;&bull;&bull;&bull;&nbsp;${last4}`;
442	
443	/** `MM/YYYY` from the raw Stripe expiry fields — never guessed, only formatted. */
444	const expiryLabel = (expMonth: number, expYear: number) => `${String(expMonth).padStart(2, "0")}/${expYear}`;
445	
446	/** Reassurance line reused across the dunning sequence. Nothing is suspended yet. */
447	const stillRunning = (hostname: string, extra = "") =>
448	  emailBanner(`<b>${hostname}</b> is still running. Nothing has been suspended.${extra ? ` ${extra}` : ""}`, "success");
449	
450	const legacyPaymentFailed = catalogEmails.paymentFailed;
451	type LegacyPaymentFailedArgs = Parameters<typeof legacyPaymentFailed>[0];
452	
453	/**
454	 * Card charge declined — FIRST failure of the dunning sequence.
455	 *
456	 * Overloaded so the original catalog shape (`{ amount, reason, updateUrl? }`,
457	 * still used by the admin template previewer) keeps working alongside the new
458	 * renewal-dunning shape.
459	 */
460	function paymentFailed(a: LegacyPaymentFailedArgs): BuiltEmail;
461	function paymentFailed(
462	  hostname: string,
463	  amountFormatted: string,
464	  last4: string,
465	  retryDateFormatted: string,
466	  billingUrl: string,
467	): BuiltEmail;
468	function paymentFailed(
469	  a: string | LegacyPaymentFailedArgs,
470	  amountFormatted?: string,
471	  last4?: string,
472	  retryDateFormatted?: string,
473	  billingUrl?: string,
474	): BuiltEmail {
475	  if (typeof a !== "string") return legacyPaymentFailed(a);
476	  const hostname = a;
477	  const amount = amountFormatted ?? "";
478	  const card = last4 ?? "";
479	  const retryDate = retryDateFormatted ?? "";
480	  const href = billingUrl ?? `${appUrl()}/dashboard/billing`;
481	  return build({
482	    template: "payment_failed",
483	    subject: `Card declined for ${hostname} — we'll retry ${retryDate}`,
484	    preheader: `${hostname} is still running. We'll try the card again on ${retryDate}.`,
485	    eyebrow: "Payment issue",
486	    accent: "warn",
487	    heading: "We couldn't charge your card",
488	    blocks: [
489	      emailParagraph(
490	        `The renewal payment for <b>${hostname}</b> didn't go through. Declines are usually something on the bank's side — a routine fraud check, a spending limit, or a card that's been reissued — so this often isn't anything you did.`,
491	      ),
492	      stillRunning(hostname),
493	      emailPanel(
494	        emailKeyValue([
495	          ["Server", hostname],
496	          ["Amount due", amount],
497	          ["Card", cardLabel(card)],
498	          ["Next attempt", retryDate],
499	        ]),
500	        "warn",
501	      ),
502	      emailParagraph(
