35	const DEFAULT_MAX_AGE_DAYS = 60; // and don't bother past this long — the mail is likely stale/dead
36	
37	const MAX_SENDS_PER_SWEEP = 25;
38	const SEND_GAP_MS = 1200;
39	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
40	
41	function winbackExpiresLabel(now = new Date()): string {
42	  const lastDayNextMonth = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 2, 0));
43	  return lastDayNextMonth.toLocaleDateString("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
44	}
