46	export async function dormantWinbackSweep(): Promise<void> {
47	  // ===== MASTER KILL-SWITCH (first line) =====
48	  const envOn = process.env.DORMANT_WINBACK_ENABLED === "true";
49	  if (!envOn && !(await getSettingBool("dormant_winback_enabled", false))) return;
50	
51	  let delayDays = await getSettingInt("dormant_winback_delay_days", DEFAULT_DELAY_DAYS);
52	  let maxAgeDays = await getSettingInt("dormant_winback_max_age_days", DEFAULT_MAX_AGE_DAYS);
53	  if (delayDays < 1) delayDays = DEFAULT_DELAY_DAYS;
54	  // GUARD: same reasoning as deploy-winback — a misconfigured window that
55	  // collapses to empty falls back to the default rather than silently
56	  // selecting no one.
57	  if (maxAgeDays <= delayDays) maxAgeDays = DEFAULT_MAX_AGE_DAYS;
58	
59	  // CANDIDATES: real-customer accounts (lib/retention.ts's own "real customer"
60	  // scope) that are past the delay, within the max age, and have NEVER
61	  // returned at all (not even the looser 1-day bar) — the same underlying
62	  // union-of-activity query the /admin/retention page renders.
63	  const rows = await signupRetentionRows();
64	  let candidates = rows.filter(
65	    (r) => !r.returned1d && r.daysSinceSignup >= delayDays && r.daysSinceSignup <= maxAgeDays,
66	  );
67	  if (candidates.length === 0) return;
68	
69	  // NEVER overlap with deploy-winback's audience. lib/retention.ts's activity
70	  // union doesn't include DeployFunnelEvent (the wizard's own VisitTracker
71	  // never mounts inside the portal), so someone who started the wizard and
72	  // left — deploy-winback's exact target — would otherwise also show up here
73	  // as "no activity" and get BOTH campaigns' discount codes for the same
74	  // underlying behaviour. Excluding anyone with ANY funnel event (started,
75	  // errored, or completed) makes the two audiences disjoint by construction:
76	  // touched the wizard at all → deploy-winback's territory; never touched it
77	  // → this sweep's.
78	  const funnelTouched = await db.deployFunnelEvent
79	    .findMany({
80	      where: { userId: { in: candidates.map((c) => c.id) } },
81	      distinct: ["userId"],
82	      select: { userId: true },
83	    })
84	    .catch(() => null); // table not present on this environment yet — no-op
85	  if (funnelTouched) {
86	    const touchedIds = new Set(funnelTouched.map((f) => f.userId));
87	    candidates = candidates.filter((c) => !touchedIds.has(c.id));
88	  }
89	  if (candidates.length === 0) return;
90	  const candidateIds = candidates.map((c) => c.id);
91	
92	  // Already sent this win-back → dedupe (same "once per retention window"
93	  // caveat as deploy-winback: EmailLog is pruned ~90 days).
94	  const alreadySent = await db.emailLog.findMany({
95	    where: { userId: { in: candidateIds }, template: DORMANT_WINBACK_TEMPLATE_TAG, status: "SENT" },
96	    distinct: ["userId"],
97	    select: { userId: true },
98	  });
99	  const alreadySentIds = new Set(alreadySent.map((e) => e.userId).filter((x): x is string => !!x));
100	
101	  const users = await db.user.findMany({
102	    where: { id: { in: candidateIds } },
103	    select: { id: true, name: true, email: true, emailVerifiedAt: true },
104	  });
105	  const userById = new Map(users.map((u) => [u.id, u]));
106	
107	  const expiresLabel = winbackExpiresLabel(new Date());
108	  const dashboardUrl = `${appUrl()}/dashboard`;
109	
110	  let considered = 0;
111	  let sent = 0;
112	  let skipped = 0;
113	  let failed = 0;
114	
115	  for (const userId of candidateIds) {
116	    if (sent >= MAX_SENDS_PER_SWEEP) break;
117	    considered++;
118	
119	    const u = userById.get(userId);
120	    if (!u) { skipped++; continue; }
121	    if (alreadySentIds.has(userId)) { skipped++; continue; }
122	    if (!u.email) { skipped++; continue; }
123	    if (!u.emailVerifiedAt) { skipped++; continue; }
124	
125	    let deliverable = true;
126	    try {
127	      deliverable = await mayDeliverTo(userId, "product_news", "email");
128	    } catch {
129	      deliverable = true;
130	    }
131	    if (!deliverable) { skipped++; continue; }
132	
133	    try {
134	      const unsubUrl = marketingUnsubUrl(userId);
135	      const built = emails.dormantWinback({
136	        name: u.name,
137	        couponCode: DORMANT_WINBACK_COUPON_CODE,
138	        percentOff: DORMANT_WINBACK_PERCENT_OFF,
139	        expiresLabel,
140	        dashboardUrl,
141	        unsubscribeUrl: unsubUrl,
142	      });
143	      const ok = await sendMail({
144	        to: u.email,
145	        subject: built.subject,
146	        html: built.html,
147	        template: built.template,
148	        listUnsubscribeUrl: unsubUrl,
149	        userId,
150	        kind: "product_news",
151	      });
152	      if (ok) sent++;
153	      else failed++;
154	    } catch (e) {
155	      failed++;
156	      console.error(`[dormant-winback] send failed for user ${userId}`, e);
157	    }
158	
159	    await sleep(SEND_GAP_MS);
160	  }
161	
162	  if (sent > 0 || failed > 0) {
163	    console.log(
164	      `[dormant-winback] sweep complete — considered ${considered}/${candidateIds.length}, sent ${sent}, skipped ${skipped}, failed ${failed}`,
165	    );
166	  }
167	}
