1	import "server-only";
2	import { z } from "zod";
3	import { db } from "./db";
4	import { sendMail, emails } from "./mailer";
5	
6	/**
7	 * Shared reply-writing core for support tickets and live chat, extracted from
8	 * lib/actions-support.ts's `replyTicket` and lib/actions-chat.ts's
9	 * `replyToConversation` so there is exactly ONE code path that writes a
10	 * reply, regardless of which surface triggers it: the existing "use server"
11	 * actions behind /dashboard/support and /admin/chat, or the new Discord
12	 * bridge webhook (app/api/webhooks/discord/route.ts).
13	 *
14	 * SECURITY — READ THIS BEFORE CALLING EITHER FUNCTION BELOW.
15	 *
16	 * Neither function performs ANY authorization check. That is deliberate, not
17	 * an oversight: `lib/actions-support.ts`'s own top-of-file comment documents a
18	 * real, previously-shipped RBAC bug in this exact reply path (a SUPPORT agent
19	 * could silently neither answer nor close a ticket that wasn't their own), so
20	 * this extraction is surgical — the DB-write body moved here VERBATIM, auth
21	 * stayed put. Every existing caller still does its own guard before calling
22	 * in:
23	 *   - `replyTicket` (lib/actions-support.ts) calls `requireTicketActor()` first.
24	 *   - `replyToConversation`/`replyWithAttachment` (lib/actions-chat.ts) call
25	 *     `requireArea("support")` first.
26	 *   - The Discord webhook route's "auth" is Discord's own Ed25519
27	 *     interaction-signature verification (lib/discord.ts's
28	 *     `verifyDiscordSignature`) PLUS `lib/discord-bridge.ts`'s
29	 *     `resolveDiscordReplyActor`, which resolves the real Discord user who
30	 *     submitted the reply (via `interaction.member.user.id`) to a Nxeon
31	 *     `User.discordUserId` link and re-checks that account still has support
32	 *     access — see that file's top-of-file comment for the full design
33	 *     (real per-person linking via OAuth, no fallback to a single shared
34	 *     identity).
35	 *
36	 * Do NOT add a new caller of `writeTicketReply`/`writeChatReply` without first
37	 * adding its own auth check — these functions will happily write a reply
38	 * attributed to whatever actorId/staffId they're given.
39	 */
40	
41	/** Write a ticket reply. Mirrors `replyTicket`'s exact prior DB-write body. */
42	export async function writeTicketReply(args: {
43	  /** The id of the user the message is authored as (TicketMessage.authorId). */
44	  actorId: string;
45	  /** Whether the calling actor is support staff (before the same-ticket-owner override below). */
46	  actorIsSupportStaff: boolean;
47	  ticketId: string;
48	  body: string;
49	  /** Optional single attachment (image or document) — see lib/ticket-attachment.ts. */
50	  attachment?: { mime: string; name: string; size: number; data: Buffer };
51	}): Promise<{ error?: string; isStaff?: boolean; ticketUserId?: string; subject?: string }> {
52	  const body = args.body.trim();
53	  // A message with an attachment and no caption is allowed (mirrors the chat
54	  // widget's image-only messages), so the length floor only applies when there
55	  // is no attachment to carry the message on its own.
56	  if (!args.attachment && (body.length < 2 || body.length > 10000)) return { error: "Message too short." };
57	  if (body.length > 10000) return { error: "Message is too long." };
58	
59	  const ticket = await db.ticket.findUnique({ where: { id: args.ticketId } });
60	  if (!ticket) return { error: "Ticket not found." };
61	  // A staff member replying to their OWN ticket (as its customer) is not a
62	  // "staff reply" — exactly the same override the original action applied.
63	  const isStaff = args.actorIsSupportStaff && ticket.userId !== args.actorId;
64	  if (ticket.userId !== args.actorId && !args.actorIsSupportStaff) return { error: "Forbidden." };
65	
66	  await db.$transaction([
67	    db.ticketMessage.create({
68	      data: {
69	        ticketId: args.ticketId,
70	        body,
71	        authorId: args.actorId,
72	        isStaff,
73	        ...(args.attachment
74	          ? {
75	              attachmentData: new Uint8Array(args.attachment.data),
76	              attachmentMime: args.attachment.mime,
77	              attachmentName: args.attachment.name,
78	              attachmentSize: args.attachment.size,
79	            }
80	          : {}),
81	      },
82	    }),
83	    db.ticket.update({
84	      where: { id: args.ticketId },
85	      data: { status: isStaff ? "ANSWERED" : "CUSTOMER_REPLY" },
86	    }),
87	  ]);
88	
89	  if (isStaff) {
90	    await db.notification.create({
91	      data: {
92	        userId: ticket.userId,
93	        title: `Support replied: ${ticket.subject}`,
94	        href: `/dashboard/support/${args.ticketId}`,
95	      },
96	    });
97	    // Also EMAIL the customer the staff reply — an in-app bell alone is easy to
98	    // miss. Best-effort: a mail failure must never fail the reply itself.
99	    try {
100	      const customer = await db.user.findUnique({ where: { id: ticket.userId }, select: { email: true } });
101	      if (customer?.email) {
102	        const tpl = emails.ticketReply({
103	          ticketId: args.ticketId,
104	          subject: ticket.subject,
105	          replyPreview: body,
106	        });
107	        await sendMail({
108	          to: customer.email,
109	          subject: tpl.subject,
110	          html: tpl.html,
111	          template: tpl.template,
112	          userId: ticket.userId,
113	          kind: "support_reply",
114	        });
115	      }
116	    } catch (e) {
117	      console.error("[support] staff-reply email failed (non-fatal)", e);
118	    }
119	  } else {
120	    const admins = await db.user.findMany({ where: { role: "ADMIN" } });
121	    await db.notification.createMany({
122	      data: admins.map((a) => ({
123	        userId: a.id,
124	        title: `Ticket reply: ${ticket.subject}`,
125	        href: `/admin/support/${args.ticketId}`,
126	      })),
127	    });
128	  }
129	
130	  return { isStaff, ticketUserId: ticket.userId, subject: ticket.subject };
131	}
132	
133	/** Write a chat reply. Mirrors `replyToConversation`'s exact prior DB-write body. */
134	export async function writeChatReply(args: {
135	  conversationId: string;
136	  body: string;
137	  /** The staff/admin user id the reply is attributed to (assignedToId). */
138	  staffId: string;
139	}): Promise<{ error?: string; ok?: boolean; conversationUserId?: string | null }> {
140	  const parsed = z
141	    .object({ id: z.string().min(1), body: z.string().trim().min(1).max(5000) })
142	    .safeParse({ id: args.conversationId, body: args.body });
143	  if (!parsed.success) return { error: "Message must be between 1 and 5000 characters." };
144	
145	  const convo = await db.chatConversation.findUnique({ where: { id: parsed.data.id } });
146	  if (!convo) return { error: "Conversation not found." };
147	
148	  await db.$transaction([
149	    db.chatMessage.create({
150	      data: { conversationId: parsed.data.id, sender: "agent", body: parsed.data.body },
151	    }),
152	    db.chatConversation.update({
153	      where: { id: parsed.data.id },
154	      data: {
155	        status: "OPEN",
156	        unreadForUser: true,
157	        unreadForAgent: false,
158	        assignedToId: args.staffId,
159	        lastMessageAt: new Date(),
160	      },
161	    }),
162	  ]);
163	
164	  // If the visitor is a signed-in customer, drop them a notification.
165	  if (convo.userId) {
166	    await db.notification
167	      .create({
168	        data: {
169	          userId: convo.userId,
170	          title: "New reply in your live chat",
171	          href: "/dashboard",
172	        },
173	      })
174	      .catch(() => {});
175	  }
176	
177	  return { ok: true, conversationUserId: convo.userId };
178	}
